cd /app/dclm && cat > /tmp/sanitize.py <<'EOF'
import sys, io
REPL = {
 b"AKIA1234567890123456": b"<your-aws-access-key-id>",
 b"D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF": b"<your-aws-secret-access-key>",
 b"ghp_aBcDeFgHiJkLmNoPqRsTuVwXyZ0123456789": b"<your-github-token>",
 b"hf_abcdefghijklmnopqrstuvwxyz123456": b"<your-huggingface-token>",
}
for p in sys.argv[1:]:
    d = open(p,'rb').read()
    o = d
    for k,v in REPL.items(): d = d.replace(k,v)
    if d != o:
        open(p,'wb').write(d); print("sanitized", p)
EOF
python3 /tmp/sanitize.py ray_processing/process.py ray_processing/ray_cluster.yaml && git diff --stat

